// repairs.js
let selectedRepair=null,repairFilter='pending';
paths.pants='<path d="M6 3h12l2 18h-7l-1-10-1 10H4L6 3Zm0 4h12M12 3v5"/>';
const repairLabels={pending:'Por hacer',working:'Lo estás haciendo',review:'Por revisar',ready:'Lista para el cliente',delivered:'Entregada al cliente'};
const repairMoney=n=>'S/ '+Number(n||0).toFixed(2);
function selected(){return state.repairs.find(r=>r.id===selectedRepair)}
function group(r){return r.stage==='pending'?'pending':r.stage==='ready'||r.stage==='delivered'?'ready':'working'}
function navigate(p){page=p;selectedRepair=null;render();scrollAppTop()}
function openRepair(id){if(holder(id)!==currentPerson)return;selectedRepair=id;page='inicio';render();scrollAppTop()}
function goBack(){selectedRepair=null;render();scrollAppTop()}
function setRepairFilter(value){repairFilter=value;render()}
function garmentArt(r){return '<span class="repair-garment">'+icon(r.kind||'shirt')+'</span>'}
function repairList(){const rows=myRepairs().filter(r=>group(r)===repairFilter);return '<div class="greeting"><p class="eyebrow">HOLA, '+esc(currentPerson.toUpperCase())+'</p><h1>Mis trabajos</h1><p class="sub">Tus arreglos, tus acuerdos y el cuidado de cada prenda.</p></div><section class="purple-welcome team-hero"><div class="welcome-content"><span class="welcome-kicker">PASO A PASO, JUNTAS</span><h2>Tu talento, en cada puntada.</h2><p>Organiza tus arreglos y acuerda apoyo cuando lo necesites.</p><button class="team-hero-btn" onclick="composeSupport()">'+icon('team')+' Pedir apoyo</button></div></section>'+incomingBanner()+'<div class="section-label"><h2>Mis arreglos</h2><span>'+myRepairs().length+' prendas</span></div><div class="repair-tabs">'+[['pending','Por hacer'],['working','En curso'],['ready','Listos']].map(([v,label])=>'<button class="'+(v===repairFilter?'selected':'')+'" onclick="setRepairFilter(\''+v+'\')">'+label+' <span>'+myRepairs().filter(r=>group(r)===v).length+'</span></button>').join('')+'</div><div class="repair-list">'+rows.map(r=>'<button class="repair-card" onclick="openRepair(\''+r.id+'\')"><div class="repair-card-top">'+garmentArt(r)+'<div><span class="ticket">'+r.id+' · '+esc(r.client)+'</span><h2>'+esc(r.task)+'</h2><p>'+esc(r.garment)+'</p></div></div><div class="repair-card-bottom"><span>'+esc(workDue(r))+'</span><span>'+repairLabels[r.stage]+'</span></div></button>').join('')+(rows.length?'':'<div class="panel empty"><h3>No tienes trabajos en esta sección</h3><p>Los nuevos acuerdos aparecerán en Apoyos.</p></div>')+'</div>'}
function repairDetail(){const r=selected();if(!r)return repairList();return '<button class="back-link" onclick="goBack()">← Mis trabajos</button><div class="greeting"><p class="eyebrow">'+r.id+' · '+esc(r.client)+'</p><h1>'+esc(r.task)+'</h1><p class="sub">'+esc(r.garment)+'</p></div><section class="task-card"><div class="task-body"><p><strong>Lo que pidió el cliente</strong></p><p>'+esc(r.instructions||'Sin indicaciones adicionales')+'</p><dl class="profile-facts"><div><dt>Fecha de mi trabajo</dt><dd>'+esc(workDue(r))+'</dd></div><div><dt>Sede responsable del cliente</dt><dd>'+esc(responsibleBranch(r))+'</dd></div><div><dt>Responsable del arreglo</dt><dd>'+esc(holder(r.id))+'</dd></div><div><dt>Estado del trabajo</dt><dd>'+repairLabels[r.stage]+'</dd></div></dl><div class="worker-actions">'+(r.stage==='pending'?button('Empezar este trabajo',"startRepair()",true,'shirt'):r.stage==='working'?button('Terminé este trabajo','finishRepair()',true,'check'):r.stage==='review'?'<div class="notice">Ya terminaste. Ahora falta que revisen tu trabajo.</div>':r.stage==='ready'?'<div class="repair-success">El arreglo está aprobado y listo para el cliente.</div>':'<div class="repair-success">Prenda entregada al cliente.</div>')+(['pending','working'].includes(r.stage)?button('Pedir apoyo',"composeSupport('"+r.id+"')",false,'team'):'')+'</div>'+(r.issue?'<div class="notice">Aviso: '+esc(r.issue)+'</div>':'')+(r.stage!=='delivered'?button('Necesito ayuda','help()',false,'help'):'')+'</div></section>'}
function startRepair(){const r=selected();if(!r||holder(r.id)!==currentPerson||r.stage!=='pending')return;modal('Empezar el arreglo','<p>Empieza cuando tengas la prenda y las indicaciones estén claras.</p><div class="modalactions">'+button('Volver','dialog.close()')+button('Sí, voy a empezar',"confirmStartRepair()",true)+'</div>')}
function confirmStartRepair(){const r=selected();if(!r||holder(r.id)!==currentPerson||r.stage!=='pending')return;r.stage='working';dialog.close();save(currentPerson+' empezó el arreglo '+r.id+'.');toast('Trabajo en curso. Toca Terminé cuando acabes.')}
function finishRepair(){const r=selected();if(!r||r.stage!=='working')return;modal('Revisa antes de terminar','<p>Comprueba las indicaciones, las costuras y el acabado de '+esc(r.garment)+'.</p><p>Después quedará pendiente la revisión de calidad.</p><div class="modalactions">'+button('Seguir trabajando','dialog.close()')+button('Terminé el arreglo','confirmFinished()',true,'check')+'</div>')}
function confirmFinished(){const r=selected();if(!r||holder(r.id)!==currentPerson||r.stage!=='working')return;r.stage='review';r.finishedAt=Date.now();dialog.close();save(currentPerson+' terminó '+r.id+'. Pendiente de revisión de calidad.');toast('Guardado. Ahora falta que revisen tu trabajo.')}
function help(){modal('¿Qué necesitas?','<p>No necesitas explicar asuntos personales.</p><div class="help-options">'+['Necesito aclarar el arreglo','Me falta un material','Tengo un problema con la máquina','Necesito más tiempo'].map(s=>button(s,"helpConfirm('"+s+"')")).join('')+'</div>')}
function helpConfirm(reason){modal('Registrar aviso','<p>'+esc(reason)+'</p><div class="modalactions">'+button('Volver','help()')+button('Guardar aviso',"sendHelp('"+reason+"')",true)+'</div>')}
function sendHelp(reason){const r=selected();if(r)r.issue=reason;else state.repairHelp=reason;dialog.close();save(currentPerson+' pidió ayuda'+(r?' en '+r.id:'')+': '+reason);toast('Aviso guardado para la dueña.')}
function helpPage(){return '<div class="greeting"><h1>Estamos para ayudarte</h1><p class="sub">Deja un aviso para organizar el trabajo contigo.</p></div>'+button('Necesito ayuda','help()',true,'help')+(state.repairHelp?'<div class="notice">'+esc(state.repairHelp)+'</div>':'')}
function render(){main.innerHTML=selectedRepair?repairDetail():page==='apoyo'?helpPage():repairList()}

