// team.js
let currentPerson='Rosa',composeDraft=null;
const teamPeople=['Rosa','Carmen','Lucía'];
const nowText=()=>new Date().toLocaleString('es-PE',{timeZone:'America/Lima',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
function teamDate(value){return new Date(value+'T12:00:00-05:00').toLocaleDateString('es-PE',{timeZone:'America/Lima',weekday:'long',day:'numeric',month:'long'})}
function initWorkScope(){
 state.supportRequests??=[];
 if(!state.workScopeVersion){
   for(const r of state.repairs){let person=r.responsible||r.receivedBy||'Rosa';for(const t of state.teamParcels||[]){const i=t.items.find(i=>i.repairId===r.id);if(i?.receipt==='received'&&!i.returned)person=t.to}if(r.returnTransfer?.stage==='received')person=r.returnTransfer.receivedBy||person;r.responsible=person;
     if(['out_wait','out_route','out_arrived'].includes(r.stage)){r.legacyLogisticsStage=r.stage;r.stage='pending'}
     if(['return_wait','return_pickup','return_route'].includes(r.stage)){r.legacyLogisticsStage=r.stage;r.stage='review'}
   }
   for(const t of state.teamParcels||[]){if(state.supportRequests.some(a=>a.legacyParcelId===t.id))continue;state.supportRequests.push({id:'AP-'+t.id,legacyParcelId:t.id,from:t.from,to:t.to,repairIds:t.items.map(i=>i.repairId),due:t.due,payment:t.payment,note:t.note,status:t.stage==='requested'?'pending':t.stage==='declined'?'declined':'accepted',createdAt:t.history?.[0]?.at||0})}
   state.workScopeVersion=1;
   try{localStorage.setItem('hilando-v1',JSON.stringify(state))}catch{}
 }
}
initWorkScope();
function holder(id){const r=state.repairs.find(r=>r.id===id);return r?.responsible||r?.receivedBy||'Rosa'}
function myRepairs(){return state.repairs.filter(r=>holder(r.id)===currentPerson)}
function workAgreement(r){return [...state.supportRequests].reverse().find(a=>a.status==='accepted'&&a.to===holder(r.id)&&a.repairIds.includes(r.id))}
function workDue(r){const a=workAgreement(r);return a?.due?teamDate(a.due):r.date}
function supportActive(id){return state.supportRequests.some(a=>a.repairIds.includes(id)&&a.status==='pending')}
function eligibleRepairs(){return myRepairs().filter(r=>['pending','working'].includes(r.stage)&&!supportActive(r.id))}
function personaChanged(name){if(![...teamPeople,'Dueña'].includes(name))return;currentPerson=name;repairFilter='pending';navigate(name==='Dueña'?'overview':'inicio')}
function personaControl(){return '<details class="persona-demo"><summary>Probar otra vista · Demostración</summary><p>Son perfiles de prueba en este navegador.</p><label>Estoy probando como<select id="demo-person" onchange="personaChanged(this.value)">'+[...teamPeople,'Dueña'].map(n=>'<option '+(n===currentPerson?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select></label></details>'}
function incomingBanner(){const n=state.supportRequests.filter(a=>a.to===currentPerson&&a.status==='pending').length;return n?'<button class="incoming-banner" onclick="navigate(\'team\')">'+icon('team')+' '+n+' solicitudes de apoyo por responder</button>':''}
function supportStatus(a){return {pending:'Esperando respuesta',accepted:'Apoyo aceptado',declined:'No aceptado',cancelled:'Cancelado'}[a.status]||'Por revisar'}
function supportCard(a){return '<section class="profile-sheet"><h3>'+esc(a.from)+' → '+esc(a.to)+'</h3><p>'+a.repairIds.map(id=>{const r=state.repairs.find(r=>r.id===id);return esc(r?r.garment+' · '+id:id)}).join('<br>')+'</p><p>'+esc(a.note)+'</p><p>Fecha: '+esc(teamDate(a.due))+'<br>Pago por el apoyo: '+repairMoney(a.payment)+'</p><strong>'+supportStatus(a)+'</strong>'+(a.status==='pending'&&a.to===currentPerson?'<div class="modalactions">'+button('Sí, puedo ayudar',"answerWorkSupport('"+a.id+"',true)",true,'check')+button('Ahora no puedo',"answerWorkSupport('"+a.id+"',false)")+'</div>':'')+(a.status==='pending'&&a.from===currentPerson?button('Cancelar solicitud',"cancelWorkSupport('"+a.id+"')"):'')+'</section>'}
function teamPage(){const rows=state.supportRequests.filter(a=>a.from===currentPerson||a.to===currentPerson);return '<div class="greeting"><p class="eyebrow">NOS ORGANIZAMOS JUNTAS</p><h1>Ayuda entre compañeras</h1><p class="sub">Elige quién puede ayudarte y acuerden la fecha y el pago.</p></div>'+button('Pedir ayuda a una compañera','composeSupport()',true,'team')+'<div class="parcel-list">'+rows.map(supportCard).join('')+(rows.length?'':'<div class="panel empty">Todavía no hay acuerdos de apoyo.</div>')+'</div>'}
function composeSupport(preselect){const rows=eligibleRepairs();if(!rows.length){modal('No hay arreglos disponibles','<p>Puedes pedir apoyo con trabajos pendientes o en curso que no tengan otra solicitud por responder.</p>');return}composeDraft={selected:preselect?[preselect]:[]};modal('¿Con qué necesitas apoyo?','<form id="pick-items"><div class="choose-items">'+rows.map(r=>'<label class="choose-row"><input name="repair" type="checkbox" value="'+r.id+'" '+(r.id===preselect?'checked':'')+'><span>'+esc(r.garment)+' · '+r.id+'</span></label>').join('')+'</div><div class="modalactions"><button class="btn" type="button" onclick="dialog.close()">Volver</button><button class="btn primary">Continuar</button></div></form>');document.getElementById('pick-items').onsubmit=e=>{e.preventDefault();composeDraft.selected=[...document.querySelectorAll('input[name="repair"]:checked')].map(i=>i.value);if(!composeDraft.selected.length){toast('Elige al menos un arreglo.');return}composeDetails()}}
function composeDetails(){const people=teamPeople.filter(n=>n!==currentPerson);if(!people.length)return;modal('Pedir ayuda a una compañera','<form id="support-form"><label class="field">¿A qué compañera?<select id="support-to">'+people.map(n=>'<option>'+esc(n)+'</option>').join('')+'</select></label><div class="colleague-summary" id="colleague-summary"></div><label class="field">¿Para qué día necesitas la ayuda?<input id="support-date" type="date" required></label><label class="field">¿Cuánto acordaron pagar? (S/)<input id="support-pay" type="number" min="0" step="0.01" required></label><label class="field">¿Qué necesitas que haga?<textarea id="support-note" maxlength="500" required></textarea></label><div class="modalactions"><button type="button" class="btn" onclick="dialog.close()">Volver</button><button class="btn primary">Revisar acuerdo</button></div></form>');const target=document.getElementById('support-to');if(composeDraft.to)target.value=composeDraft.to;document.getElementById('support-date').value=composeDraft.due||'';document.getElementById('support-pay').value=composeDraft.payment??'';document.getElementById('support-note').value=composeDraft.note||'';const summary=()=>document.getElementById('colleague-summary').innerHTML=colleagueSummary(target.value);target.onchange=summary;summary();document.getElementById('support-form').onsubmit=e=>{e.preventDefault();const note=document.getElementById('support-note').value.trim(),payment=Number(document.getElementById('support-pay').value);if(!note||!Number.isFinite(payment)||payment<0)return;Object.assign(composeDraft,{to:target.value,due:document.getElementById('support-date').value,payment,note});reviewWorkSupport()}}
function reviewWorkSupport(){const d=composeDraft;modal('Revisar acuerdo','<p><strong>'+esc(currentPerson)+' → '+esc(d.to)+'</strong></p><p>'+d.selected.map(id=>{const r=state.repairs.find(r=>r.id===id);return esc(r.garment)+' · '+id}).join('<br>')+'</p><p>'+esc(d.note)+'</p><p>Fecha: '+esc(teamDate(d.due))+'<br>Pago por el apoyo: '+repairMoney(d.payment)+'</p><div class="modalactions">'+button('Volver a editar','composeDetails()')+button('Guardar solicitud','saveWorkSupport()',true)+'</div>')}
function saveWorkSupport(){const d=composeDraft;if(!d||!d.selected.length||!d.to||!teamPeople.includes(d.to)||d.to===currentPerson||!d.due||!d.note||!Number.isFinite(d.payment)||d.payment<0)return;if(d.selected.some(id=>!eligibleRepairs().some(r=>r.id===id))){toast('Algún arreglo ya cambió. Revisa tus trabajos.');return}state.supportRequests.push({id:'AP-'+Date.now().toString(36),from:currentPerson,to:d.to,repairIds:[...d.selected],due:d.due,payment:d.payment,note:d.note,status:'pending',createdAt:Date.now()});composeDraft=null;dialog.close();page='team';selectedRepair=null;save(currentPerson+' pidió apoyo a '+d.to+' con '+d.selected.join(', ')+'.');toast('Tu solicitud quedó guardada. '+d.to+' todavía debe responder.')}
function answerWorkSupport(id,accept){const a=state.supportRequests.find(a=>a.id===id);if(!a||a.to!==currentPerson||a.status!=='pending')return;const rows=a.repairIds.map(id=>state.repairs.find(r=>r.id===id));if(accept&&rows.some(r=>!r||holder(r.id)!==a.from||!['pending','working'].includes(r.stage))){toast('El trabajo cambió. Coordina un nuevo acuerdo.');return}a.status=accept?'accepted':'declined';a.answeredAt=Date.now();if(accept)for(const r of rows){r.responsible=a.to;r.stage='pending';r.supportId=a.id}save(currentPerson+(accept?' aceptó':' no pudo aceptar')+' el apoyo '+id+'.');toast(accept?'El arreglo aparece en tus trabajos.':'Respuesta guardada.')}
function cancelWorkSupport(id){const a=state.supportRequests.find(a=>a.id===id);if(!a||a.from!==currentPerson||a.status!=='pending')return;a.status='cancelled';save(currentPerson+' canceló la solicitud '+id+'.')}
function mediaDB(){return new Promise((resolve,reject)=>{const q=indexedDB.open('rapicostura-media',1);q.onupgradeneeded=()=>q.result.createObjectStore('files');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
async function mediaPut(id,file){const db=await mediaDB();try{await new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}finally{db.close()}}
render=function(){initWorkScope();if(currentPerson==='Dueña')return;main.innerHTML=(page==='team'?teamPage():page==='apoyo'?helpPage():selectedRepair?repairDetail():repairList())+personaControl();document.getElementById('mobile-nav').innerHTML=[['inicio','orders','Mis trabajos'],['team','team','Apoyos'],['apoyo','help','Ayuda']].map(([p,i,label])=>'<button class="'+(page===p?'active':'')+'" onclick="navigate(\''+p+'\')">'+icon(i)+'<span>'+label+'</span></button>').join('')};

;
// owner.js
const workerTeamRender=render;
let ownerDemo=false,ownerMember='Todas',ownerSearch='';
function ownerData(){return {repairs:state.repairs,agreements:state.supportRequests}}
function ownerPerson(r){return holder(r.id)}
function ownerLocation(r){return staffProfile(holder(r.id)).mode}
function ownerRefresh(){try{const next=JSON.parse(localStorage.getItem('hilando-v1'));if(Array.isArray(next?.repairs))state=next}catch{}initWorkScope();render();toast('Registros locales actualizados.')}
function ownerModeBar(){return '<div class="owner-mode"><span>SECCIÓN DE TRABAJO</span></div><p class="owner-local-note">Registros de este navegador. Los cambios todavía no se comparten entre celulares.</p>'}
function ownerEvents(){return (state.activity||[]).filter(a=>a.scope==='work').map((a,i)=>({...a,who:a.who||'Equipo',order:a.at||-i}))}
function ownerAlerts(){const d=ownerData();return [...d.repairs.filter(r=>r.issue).map(r=>({kind:'help',title:holder(r.id)+' necesita apoyo',description:r.issue,repair:r.id,label:'Ver arreglo',icon:'help'})),...d.repairs.filter(r=>r.stage==='review').map(r=>({kind:'quality',title:'Revisión de calidad pendiente',description:r.garment+' · '+responsibleBranch(r),repair:r.id,label:'Ver arreglo',icon:'check'}))]}
function eventCard(e){return '<div class="owner-event"><span class="event-avatar">'+esc((e.who||'E')[0])+'</span><span class="event-copy"><strong>'+esc(e.who)+'<small>'+esc(e.time)+'</small></strong><span>'+esc(e.message)+'</span></span></div>'}
function alertCard(a){return '<div class="owner-alert help"><span>'+icon(a.icon)+'</span><div><h3>'+esc(a.title)+'</h3><p>'+esc(a.description)+'</p><button onclick="ownerOpenRepair(\''+a.repair+'\')">'+esc(a.label)+' →</button></div></div>'}
function ownerKpis(){const d=ownerData();return '<div class="owner-kpis">'+[['orders',d.repairs.filter(r=>r.stage!=='delivered').length,'Trabajos activos','members'],['check',d.repairs.filter(r=>r.stage==='review').length,'Por revisar','attention'],['team',d.agreements.filter(a=>a.status==='pending').length,'Apoyos por responder','movements'],['help',d.repairs.filter(r=>r.issue).length,'Necesitan ayuda','attention']].map(([i,n,label,p])=>'<button class="owner-kpi" onclick="ownerNavigate(\''+p+'\')"><span>'+icon(i)+'</span><strong>'+n+'</strong><small>'+label+'</small></button>').join('')+'</div>'}
function memberCard(name){const rows=ownerData().repairs.filter(r=>holder(r.id)===name&&r.stage!=='delivered');return '<button class="owner-member" onclick="ownerFilterMember(\''+name+'\')"><span class="member-initial">'+esc(name[0])+'</span><span><strong>'+esc(name)+'</strong><small>'+rows.length+' trabajos asignados</small></span><b>›</b></button>'}
function ownerHome(){const events=ownerEvents(),alerts=ownerAlerts();return ownerGreeting('Así va el trabajo','Arreglos, acuerdos de apoyo y calidad del taller.')+ownerModeBar()+'<section class="owner-hero"><div><span class="owner-hero-label">EL TRABAJO DE TU EQUIPO</span><h2>Cada prenda, bien cuidada.</h2><p>Revisa los avances y ayuda a resolver las dificultades.</p><button onclick="ownerNavigate(\'members\')">Ver equipo →</button></div></section>'+ownerKpis()+'<section class="owner-surface"><div class="owner-section-title"><h2>Necesita tu atención</h2></div>'+alerts.slice(0,4).map(alertCard).join('')+(alerts.length?'':'<p>No hay asuntos pendientes.</p>')+'</section><section class="owner-surface"><div class="owner-section-title"><h2>Actividad de trabajo</h2><button onclick="ownerNavigate(\'movements\')">Ver toda →</button></div>'+events.slice(0,4).map(eventCard).join('')+(events.length?'':'<p>Los nuevos avances y acuerdos aparecerán aquí.</p>')+'</section>'}
function ownerMovementPage(){return ownerGreeting('Actividad de trabajo','Avances, acuerdos y avisos del equipo.')+ownerModeBar()+'<section class="owner-surface">'+ownerEvents().map(eventCard).join('')+'</section><h2 class="package-heading">Acuerdos de apoyo</h2>'+ownerData().agreements.map(supportCard).join('')}
function ownerOpenRepair(id){const r=ownerData().repairs.find(r=>r.id===id);if(!r)return;modal(esc(r.garment),'<p>'+r.id+' · '+esc(r.client)+'</p><p>'+esc(r.task)+'</p><p>Responsable: '+esc(holder(r.id))+'<br>Sede: '+esc(responsibleBranch(r))+'<br>Estado: '+repairLabels[r.stage]+'</p>')}
function ownerNavigate(p){selectedRepair=null;ownerSearch='';page=p;render();scrollAppTop()}
function ownerGreeting(title,sub,eyebrow='VISTA DE LA DUEÑA'){return `<div class="owner-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="sub">${sub}</p></div><button class="owner-refresh" onclick="ownerRefresh()" aria-label="Actualizar registros">↻</button></div>`}
function ownerFilterMember(name){ownerMember=name;ownerNavigate('members')}
function ownerSetMember(name){ownerMember=name;render()}
function ownerRepairRow(r){return `<button class="owner-repair-row" onclick="ownerOpenRepair('${r.id}')"><span class="owner-prenda">${icon('shirt')}</span><span><strong>${esc(r.garment)}</strong><small>${esc(r.task)} · ${r.id}</small><em>${esc(ownerLocation(r))}</em></span><span class="owner-repair-person">${esc(ownerPerson(r))}<small>${repairLabels[r.stage]||'Pendiente'}</small></span></button>`}
function ownerMembers(){const rows=ownerData().repairs.filter(r=>(ownerMember==='Todas'||ownerPerson(r)===ownerMember)&&`${r.id} ${r.client} ${r.garment} ${r.task} ${ownerPerson(r)}`.toLowerCase().includes(ownerSearch.toLowerCase()));return ownerGreeting('Cada prenda, con su responsable','Consulta responsables y avances de los arreglos.')+ownerModeBar()+`<div class="owner-members top-members">${teamPeople.map(memberCard).join('')}</div><div class="owner-filterbar">${['Todas',...teamPeople].map(p=>`<button class="${ownerMember===p?'selected':''}" onclick="ownerSetMember('${p}')">${p}</button>`).join('')}</div><input id="owner-search" class="owner-search" aria-label="Buscar prenda, cliente o trabajadora" placeholder="Buscar prenda, cliente o trabajadora…" value="${esc(ownerSearch)}"><section class="owner-surface" id="owner-repair-results">${rows.map(ownerRepairRow).join('')||'<div class="owner-empty">No hay prendas para este filtro.</div>'}</section>`}
function ownerAttentionPage(){const alerts=ownerAlerts();return ownerGreeting('Pendientes de coordinar','Revisa los avisos y la calidad pendiente.')+ownerModeBar()+`<div class="owner-attention-grid">${alerts.map(alertCard).join('')||'<div class="owner-surface owner-empty">Todo al día. No hay asuntos pendientes.</div>'}</div><p class="owner-small-print">Acuerda los siguientes pasos con las trabajadoras.</p>`}
render=function(){document.body.classList.toggle('owner-view',currentPerson==='Dueña');document.title=currentPerson==='Dueña'?'Rapicostura · Mi taller':'Rapicostura · Mi trabajo';if(currentPerson!=='Dueña'){workerTeamRender();return}if(page==='inicio')page='overview';main.innerHTML=(page==='members'?ownerMembers():page==='movements'?ownerMovementPage():page==='attention'?ownerAttentionPage():ownerHome())+personaControl();document.querySelector('.account').innerHTML='<span class="avatar">D</span><span>Dueña<small>Mi taller</small></span>';document.getElementById('mobile-nav').innerHTML=[['overview','home','Resumen'],['members','team','Equipo'],['movements','orders','Actividad'],['attention','help','Atención']].map(([p,i,label])=>'<button class="'+(page===p?'active':'')+'" onclick="ownerNavigate(\''+p+'\')">'+icon(i)+'<span>'+label+'</span></button>').join('');const input=document.getElementById('owner-search');if(input)input.oninput=e=>{ownerSearch=e.target.value;const rows=ownerData().repairs.filter(r=>(ownerMember==='Todas'||ownerPerson(r)===ownerMember)&&(r.id+' '+r.client+' '+r.garment+' '+r.task+' '+holder(r.id)).toLowerCase().includes(ownerSearch.toLowerCase()));document.getElementById('owner-repair-results').innerHTML=rows.map(ownerRepairRow).join('')||'<div class="owner-empty">No hay prendas para este filtro.</div>'}};
window.addEventListener('storage',e=>{if(e.key==='hilando-v1'&&e.newValue){try{const next=JSON.parse(e.newValue);if(Array.isArray(next.repairs)){state=next;initWorkScope();render()}}catch{}}});
if(new URLSearchParams(location.search).get('vista')==='duena'){currentPerson='Dueña';page='overview'}

;
// profiles.js
const staffSkills=['Bastas','Cierres','Ajustes de talla','Cuellos','Puños y pretinas','Bolsillos','Elásticos'];
const staffMachines=['Recta industrial','Remalladora','Recubridora','Máquina doméstica'];
const staffBranches=['Por confirmar',...RapicosturaBranches.sites];
const baseProfileRender=render,baseOwnerMembers=ownerMembers;
let staffTab='profiles',profileStepDraft=null,intakeDraft=null;
function staffProfile(name){state.staffProfiles??={};if(!state.staffProfiles[name])state.staffProfiles[name]={name,status:teamPeople.includes(name)?'active':'applicant',skills:[],machines:[],equipment:'Por confirmar',mode:'Por confirmar',availability:'Por confirmar',schedule:'',branch:'Por confirmar',canReceive:name==='Rosa',completed:false};return state.staffProfiles[name]}
teamPeople.forEach(staffProfile);
function syncStaff(){state.staffProfiles??={};for(const p of Object.values(state.staffProfiles))if(p.status==='active'&&!teamPeople.includes(p.name))teamPeople.push(p.name);teamPeople.forEach(staffProfile)}
function safeEntry(value){return value.trim().replace(/[<>"`]/g,'')}
function staffPick(options,value){return options.map(o=>`<option ${value===o?'selected':''}>${esc(o)}</option>`).join('')}
function profileView(){const p=staffProfile(currentPerson);return `<div class="greeting"><p class="eyebrow">MI PERFIL DE TRABAJO</p><h1>${esc(p.name)}</h1><p class="sub">Lo que sabes hacer y cómo podemos organizarnos contigo.</p></div><section class="profile-banner">${icon('team')}<div><strong>${p.completed?'Perfil actualizado':'Completemos tu perfil'}</strong><p>Tu disponibilidad puede cambiar. Puedes actualizarla sin explicar asuntos personales.</p></div></section><section class="profile-sheet"><h2>Mi forma de trabajar</h2><dl class="profile-facts"><div><dt>Modalidad</dt><dd>${esc(p.mode)}</dd></div><div><dt>Disponibilidad</dt><dd>${esc(p.availability)}${p.schedule?'<small>'+esc(p.schedule)+'</small>':''}</dd></div><div><dt>Local de referencia</dt><dd>${esc(p.branch)}</dd></div><div><dt>Máquinas propias</dt><dd>${esc(p.equipment)}</dd></div></dl><button class="wide-support" onclick="editProfile()">${icon('calendar')} Actualizar mis datos</button></section><section class="profile-sheet"><h2>Lo que sé hacer</h2><div class="skill-pills">${p.skills.map(s=>`<span>${esc(s)}</span>`).join('')||'<p>Todavía no has indicado tus habilidades.</p>'}</div><h3>Máquinas que sé usar</h3><div class="skill-pills">${p.machines.map(s=>`<span>${esc(s)}</span>`).join('')||'<p>Por completar.</p>'}</div><button class="flow-help" onclick="editProfileSkills()">Editar mis habilidades</button></section><p class="local-note">Datos declarados por ti. No implican que debas aceptar todos los encargos.</p>`}
function openProfile(){navigate('profile')}
function editProfile(){const p=staffProfile(currentPerson);profileStepDraft=structuredClone(p);modal('¿Cómo puedes trabajar?',`<form id="profile-basics"><label class="field">Modalidad que prefieres<select id="staff-mode">${staffPick(['Por confirmar','En el local','Desde mi casa','Ambas opciones'],p.mode)}</select></label><label class="field">Trabajo adicional<select id="staff-availability">${staffPick(['Por confirmar','Puedo recibir trabajo','Solo mis trabajos actuales','Necesito reorganizar entregas'],p.availability)}</select></label><label class="field">Días y horarios disponibles<input id="staff-schedule" maxlength="160" value="${esc(p.schedule)}" placeholder="Ej. Lunes a viernes, de 9 a 2"></label><label class="field">Local de referencia<select id="staff-branch">${staffPick(staffBranches,p.branch)}</select></label><label class="field">¿Tienes máquinas propias?<select id="staff-equipment">${staffPick(['Por confirmar','Sí, tengo','No tengo'],p.equipment)}</select></label><p class="local-note">No necesitas compartir información familiar.</p><div class="modalactions"><button type="button" class="btn" onclick="dialog.close()">Volver</button><button class="btn primary">Continuar</button></div></form>`);document.getElementById('profile-basics').onsubmit=e=>{e.preventDefault();Object.assign(profileStepDraft,{mode:document.getElementById('staff-mode').value,availability:document.getElementById('staff-availability').value,schedule:safeEntry(document.getElementById('staff-schedule').value),branch:document.getElementById('staff-branch').value,equipment:document.getElementById('staff-equipment').value});profileSkillsForm()}}
function editProfileSkills(){profileStepDraft=structuredClone(staffProfile(currentPerson));profileSkillsForm()}
function profileSkillsForm(){const p=profileStepDraft;modal('Lo que sabes hacer',`<form id="profile-skills"><p>Marca solo lo que ya sabes hacer. Puedes cambiarlo después.</p><h3 class="profile-form-heading">Arreglos</h3><div class="profile-checks">${staffSkills.map(s=>`<label><input name="staff-skill" type="checkbox" value="${s}" ${p.skills.includes(s)?'checked':''}><span>${s}</span></label>`).join('')}</div><h3 class="profile-form-heading">Máquinas que sabes usar</h3><div class="profile-checks">${staffMachines.map(s=>`<label><input name="staff-machine" type="checkbox" value="${s}" ${p.machines.includes(s)?'checked':''}><span>${s}</span></label>`).join('')}</div><div class="modalactions"><button type="button" class="btn" onclick="dialog.close()">Volver</button><button class="btn primary">Revisar mis datos</button></div></form>`);document.getElementById('profile-skills').onsubmit=e=>{e.preventDefault();p.skills=[...document.querySelectorAll('input[name="staff-skill"]:checked')].map(i=>i.value);p.machines=[...document.querySelectorAll('input[name="staff-machine"]:checked')].map(i=>i.value);modal('Revisemos tu perfil',`<div class="notice"><strong>${esc(p.mode)}</strong><br>${esc(p.availability)}${p.schedule?'<br>'+esc(p.schedule):''}<br>Local: ${esc(p.branch)}<br>Máquinas propias: ${esc(p.equipment)}</div><p><strong>Habilidades:</strong> ${esc(p.skills.join(', ')||'Sin indicar')}</p><p><strong>Máquinas que sabes usar:</strong> ${esc(p.machines.join(', ')||'Sin indicar')}</p><div class="modalactions">${button('Corregir','profileSkillsForm()')}${button('Guardar mi perfil','saveProfile()',true)}</div>`)} }
function saveProfile(){if(!profileStepDraft)return;state.staffProfiles[currentPerson]={...profileStepDraft,completed:true,updatedAt:Date.now()};profileStepDraft=null;dialog.close();save(currentPerson+' actualizó sus habilidades y disponibilidad.');toast('Tu perfil quedó guardado.')}
function colleagueSummary(name){const p=staffProfile(name);return `<strong>${esc(name)}</strong><p>${esc(p.skills.length?p.skills.join(' · '):'Habilidades pendientes de completar')}</p><span>${esc(p.availability)}${p.schedule?' · '+esc(p.schedule):''}</span><small>${esc(p.mode)} · Local: ${esc(p.branch)}</small><small>Datos declarados. Tu compañera debe aceptar este encargo.</small>`}
function receiveGarment(keep=false){if(!staffProfile(currentPerson).canReceive){toast('La dueña debe habilitarte para recibir prendas en el local.');return}if(keep!==true)intakeDraft={};modal('Recibir una prenda · 1 de 2',`<form id="intake-first"><label class="field">Nombre del cliente<input id="intake-client" value="${esc(intakeDraft.client||'')}" maxlength="70" placeholder="Ej. Ana Pérez" required></label><label class="field">Teléfono del cliente<input id="intake-phone" value="${esc(intakeDraft.phone||'')}" type="tel" maxlength="25" placeholder="Para coordinar su entrega" required></label><label class="field">Prenda que dejó<input id="intake-garment" value="${esc(intakeDraft.garment||'')}" maxlength="70" placeholder="Ej. Pantalón azul" required></label><label class="field">Arreglo solicitado<select id="intake-task">${staffPick(['Hacer basta','Cambiar cierre','Ajustar talla','Otro arreglo'],intakeDraft.task||'Hacer basta')}</select></label><label class="field">Local donde se recibió<select id="intake-branch">${staffPick(staffBranches.filter(b=>b!=='Por confirmar'),intakeDraft.branch||staffProfile(currentPerson).branch)}</select></label><div class="modalactions"><button class="btn" type="button" onclick="dialog.close()">Volver</button><button class="btn primary">Continuar</button></div></form>`);document.getElementById('intake-first').onsubmit=e=>{e.preventDefault();intakeDraft={...intakeDraft,client:safeEntry(document.getElementById('intake-client').value),phone:safeEntry(document.getElementById('intake-phone').value),garment:safeEntry(document.getElementById('intake-garment').value),task:document.getElementById('intake-task').value,branch:document.getElementById('intake-branch').value};if(!intakeDraft.client||!intakeDraft.phone||!intakeDraft.garment)return;intakeDetails()}}
function intakeDetails(){modal('Acordar el arreglo · 2 de 2',`<form id="intake-last"><div class="notice">${esc(intakeDraft.garment)} · Cliente: ${esc(intakeDraft.client)}</div><label class="field">Indicaciones acordadas<textarea id="intake-details" maxlength="500" placeholder="Ej. Acortar 3 cm y conservar el acabado original." required>${esc(intakeDraft.instructions||'')}</textarea></label><label class="field">Fecha acordada con el cliente<input id="intake-date" type="date" value="${esc(intakeDraft.due||'')}" required></label><label class="field">Precio del arreglo al cliente (S/)<input id="intake-price" value="${intakeDraft.price??''}" type="number" inputmode="decimal" min="0" step="0.01" required></label><p class="local-note">Este es el precio al cliente, no el pago de un apoyo entre compañeras. Antes de confirmar, acuerda los datos con el cliente.</p><div class="modalactions"><button type="button" class="btn" onclick="receiveGarment(true)">Volver</button><button class="btn primary">Revisar registro</button></div></form>`);document.getElementById('intake-last').onsubmit=e=>{e.preventDefault();Object.assign(intakeDraft,{instructions:safeEntry(document.getElementById('intake-details').value),due:document.getElementById('intake-date').value,price:Number(document.getElementById('intake-price').value)});if(!intakeDraft.instructions||!Number.isFinite(intakeDraft.price))return;modal('Confirmar recepción',`<div class="notice"><strong>${esc(intakeDraft.garment)}</strong><br>${esc(intakeDraft.task)}<br>Cliente: ${esc(intakeDraft.client)}<br>Teléfono: ${esc(intakeDraft.phone)}<br>Local: ${esc(intakeDraft.branch)}</div><p>${esc(intakeDraft.instructions)}</p><p><strong>Fecha:</strong> ${esc(teamDate(intakeDraft.due))}<br><strong>Precio al cliente:</strong> ${repairMoney(intakeDraft.price)}</p><p>Recibe: <strong>${esc(currentPerson)}</strong>. Inicialmente el trabajo quedará en tu lista; puedes pedir apoyo después.</p><div class="modalactions">${button('Corregir','intakeDetails()')}${button('Registrar prenda recibida','saveIntake()',true)}</div>`)} }
function saveIntake(){if(!staffProfile(currentPerson).canReceive||!intakeDraft)return;const d=intakeDraft;let n=state.nextReceipt||107;while(state.repairs.some(r=>r.id==='RC-'+n))n++;state.nextReceipt=n+1;const r={id:'RC-'+n,client:d.client,phone:d.phone,garment:d.garment,task:d.task,instructions:d.instructions,date:teamDate(d.due),due:d.due,price:d.price,branch:d.branch,kind:/pantalón/i.test(d.garment)?'pants':'shirt',tone:'blue',stage:'pending',mode:'shop',issue:'',receivedBy:currentPerson,responsible:currentPerson,receivedAt:Date.now(),received:nowText(),location:'Local '+d.branch+' · Bolsa '+n};state.repairs.push(r);intakeDraft=null;dialog.close();selectedRepair=null;page='reception';repairFilter='pending';save(currentPerson+' recibió '+r.garment+' en '+r.branch+' · '+r.id+'.');toast('Prenda registrada: '+r.id)}
function staffCard(p){return `<section class="staff-card"><div class="staff-card-head"><span class="avatar">${esc(p.name[0])}</span><div><h3>${esc(p.name)}</h3><span>${p.status==='active'?'Trabajadora incorporada':'Postulante · Falta confirmar incorporación'}</span></div></div><div class="skill-pills">${p.skills.map(s=>`<span>${s}</span>`).join('')||'<p>Habilidades por completar</p>'}</div><p><strong>${esc(p.availability)}</strong><br>${esc(p.schedule||'Horario por confirmar')}<br>${esc(p.mode)} · Local: ${esc(p.branch)}</p><p class="local-note">Máquinas propias: ${esc(p.equipment)}<br>Sabe usar: ${esc(p.machines.join(', ')||'Por completar')}</p>${p.status==='active'?`<button class="staff-permission ${p.canReceive?'enabled':''}" onclick="toggleReception('${p.name}')">${icon(p.canReceive?'check':'plus')} ${p.canReceive?'Puede registrar prendas de clientes':'Habilitar registro de clientes'}</button>`:button('Confirmar incorporación',`approveStaff('${p.name}')`,true,'check')}</section>`}
ownerMembers=function(){if(ownerDemo)return baseOwnerMembers();const tabs=`<div class="profile-section-tabs"><button class="${staffTab==='profiles'?'selected':''}" onclick="staffTab='profiles';render()">Perfiles del equipo</button><button class="${staffTab==='garments'?'selected':''}" onclick="staffTab='garments';render()">Prendas asignadas</button></div>`;if(staffTab==='garments')return tabs+baseOwnerMembers();return ownerGreeting('Conoce y organiza a tu equipo','Habilidades declaradas, disponibilidad y local de referencia.')+ownerModeBar()+tabs+button('Registrar postulante','addApplicant()',true,'plus')+`<div class="staff-grid">${Object.values(state.staffProfiles).map(staffCard).join('')}</div><div class="notice">La postulante no recibe encargos hasta confirmar su incorporación. El chatbot de reclutamiento sigue separado: estos datos se registran manualmente en el prototipo.</div>`}
function addApplicant(){modal('Registrar una postulante',`<form id="applicant-form"><p>Registra una persona que el equipo esté evaluando. Este paso no la incorpora todavía.</p><label class="field">Nombre para identificarla<input id="applicant-name" maxlength="40" placeholder="Ej. Patricia Gómez" pattern="[A-Za-zÀ-ÿ ]{2,40}" required></label><div class="modalactions"><button class="btn" type="button" onclick="dialog.close()">Volver</button><button class="btn primary">Guardar postulante</button></div></form>`);document.getElementById('applicant-form').onsubmit=e=>{e.preventDefault();const name=document.getElementById('applicant-name').value.trim().replace(/ +/g,' ');if(!/^[\p{L} ]{2,40}$/u.test(name)||name==='Dueña')return;if(Object.keys(state.staffProfiles).some(n=>n.toLocaleLowerCase()===name.toLocaleLowerCase())){toast('Ya existe una persona con ese nombre.');return}staffProfile(name);dialog.close();save('La dueña registró a '+name+' como postulante.');toast('Postulante registrada. Falta confirmar su incorporación.')}}
function approveStaff(name){modal('Confirmar incorporación',`<p>¿Nelly o la responsable del taller confirmó la incorporación de <strong>${esc(name)}</strong>?</p><p>Al confirmar, aparecerá entre las compañeras que pueden recibir solicitudes de apoyo. Cada encargo necesita su aceptación.</p><div class="modalactions">${button('Todavía no','dialog.close()')}${button('Sí, incorporación confirmada',`confirmApproveStaff('${name}')`,true)}</div>`)}
function confirmApproveStaff(name){if(currentPerson!=='Dueña')return;staffProfile(name).status='active';syncStaff();dialog.close();save('La dueña confirmó la incorporación de '+name+'.');toast('Trabajadora incorporada. Su perfil está por completar.')}
function toggleReception(name){if(currentPerson!=='Dueña')return;const p=staffProfile(name);p.canReceive=!p.canReceive;save('La dueña '+(p.canReceive?'habilitó':'deshabilitó')+' la recepción de prendas para '+name+'.');toast(p.canReceive?'Ya puede registrar prendas recibidas.':'Recepción en el local deshabilitada.')}
render=function(){syncStaff();baseProfileRender();if(currentPerson==='Dueña')return;if(page==='profile'){main.innerHTML=profileView()+personaControl();}else if(page==='inicio'&&!selectedRepair){const list=main.querySelector('.section-label');if(staffProfile(currentPerson).canReceive&&list){const intake=document.createElement('button');intake.className='receive-new';intake.innerHTML=icon('plus')+' Recibir prenda de un cliente';intake.onclick=receiveGarment;list.before(intake)}if(!staffProfile(currentPerson).completed){const top=main.querySelector('.greeting'),hint=document.createElement('button');hint.className='complete-profile';hint.innerHTML=icon('team')+' Completar mi perfil de trabajo '+icon('arrow');hint.onclick=openProfile;top?.after(hint)}if(!myRepairs().length&&staffProfile(currentPerson).canReceive){const hero=main.querySelector('.team-hero');if(hero){hero.querySelector('h2').textContent='Todo empieza aquí.';hero.querySelector('p').textContent='Recibe la prenda y acuerda los detalles con tu cliente.';const start=hero.querySelector('.team-hero-btn');start.innerHTML=icon('plus')+' Recibir primera prenda';start.onclick=receiveGarment;main.querySelector('.receive-new')?.remove()}}}const account=document.querySelector('.account');account.innerHTML=`<button class="profile-open" onclick="openProfile()" aria-label="Abrir mi perfil"><span class="avatar">${currentPerson[0]}</span><span>${esc(currentPerson)}<small>Mi perfil</small></span></button>`};
const basicOwnerRepair=ownerOpenRepair;
ownerOpenRepair=function(id){if(ownerDemo)return basicOwnerRepair(id);const r=state.repairs.find(r=>r.id===id);if(!r)return;modal(esc(r.garment),`<p>${r.id} · Cliente: ${esc(r.client)}</p><div class="notice"><strong>${esc(r.task)}</strong><br>${esc(r.instructions||'Sin indicaciones adicionales')}</div><dl class="profile-facts"><div><dt>Recibió la prenda</dt><dd>${esc(r.receivedBy||'No registrado en el ejemplo anterior')}</dd></div><div><dt>Responsable actual del arreglo</dt><dd>${esc(ownerPerson(r))}</dd></div><div><dt>Fecha acordada</dt><dd>${esc(r.date)}</dd></div></dl>${r.phone?'<p>Contacto del cliente: '+esc(r.phone)+'</p>':''}`)};

;
// reception.js
const beforeReceptionRender=render;
function receptionRecords(){return state.repairs.filter(r=>r.receivedBy&&(currentPerson==='Dueña'||r.receivedBy===currentPerson)).sort((a,b)=>(b.receivedAt||0)-(a.receivedAt||0))}
function receptionCard(r){return `<button class="reception-record" onclick="receptionRecord('${r.id}')"><span class="reception-garment">${icon(r.kind||'shirt')}</span><span><strong>${esc(r.garment)}</strong><small>${r.id} · Cliente: ${esc(r.client)}</small><em>${esc(r.task)} · ${esc(r.date)}</em><b>Recibió ${esc(r.receivedBy)} · Responsable actual: ${esc(holder(r.id))}</b></span><i>›</i></button>`}
function receptionPage(){const owner=currentPerson==='Dueña',rows=receptionRecords(),allowed=owner||staffProfile(currentPerson).canReceive;return `${owner?'<button class="back-link" onclick="ownerNavigate(\'overview\')">← Resumen del taller</button>':''}<div class="greeting"><p class="eyebrow">${owner?'RECEPCIÓN DEL LOCAL':'TU TAREA EN EL LOCAL'}</p><h1>${owner?'Prendas de clientes':'Prendas de clientes'}</h1><p class="sub">${owner?'Consulta el encargo del cliente y quién está haciendo el arreglo.':'Cuando un cliente deje una prenda, regístrala aquí.'}</p></div>${!owner&&allowed?`<section class="reception-hero"><span class="reception-icon">${icon('location')}</span><div><span class="reception-tag">ENCARGADA DE RECEPCIÓN</span><h2>${esc(currentPerson)}, tú recibes la prenda.</h2><p>Registra lo que pidió el cliente. Después puedes hacer el arreglo o pedir apoyo a una compañera.</p></div><button onclick="receiveGarment()">${icon('plus')} Recibir prenda del cliente</button></section>`:owner?ownerReceptionInfo():'<div class="notice">La dueña debe habilitarte para registrar prendas recibidas en el local.</div>'}<div class="section-label"><h2>${owner?'Registro del local':'Lo que recibiste'}</h2><span>${rows.length} ${rows.length===1?'prenda':'prendas'}</span></div><div class="reception-records">${rows.map(receptionCard).join('')||`<div class="reception-empty">${icon('box')}<h3>Aún no hay prendas registradas</h3><p>${owner?'Los registros aparecerán cuando la encargada reciba una prenda del cliente.':'Toca “Recibir prenda del cliente” cuando alguien deje su encargo.'}</p></div>`}</div>${!owner?'<button class="flow-help" onclick="navigate(\'apoyo\')">'+icon('help')+' Necesito ayuda con la recepción</button>':''}`}
function receptionRecord(id){const r=state.repairs.find(r=>r.id===id);if(!r)return;if(currentPerson!=='Dueña'&&r.receivedBy!==currentPerson)return;modal('Registro de recepción',`<p><strong>${esc(r.garment)} · ${r.id}</strong></p><div class="notice">Cliente: ${esc(r.client)}<br>Contacto: ${esc(r.phone||'No registrado')}<br>Arreglo: ${esc(r.task)}</div><p>${esc(r.instructions)}</p><dl class="profile-facts"><div><dt>Recibió al cliente</dt><dd>${esc(r.receivedBy)} · ${esc(r.received||'')}</dd></div><div><dt>Local de recepción</dt><dd>${esc(r.branch||'Rapicostura')}</dd></div><div><dt>Responsable actual del arreglo</dt><dd>${esc(holder(r.id))}</dd></div><div><dt>Entrega acordada</dt><dd>${esc(r.date)}</dd></div><div><dt>Precio al cliente</dt><dd>${repairMoney(r.price)}</dd></div></dl>${holder(r.id)===currentPerson?button('Ver mi trabajo',`dialog.close();openRepair('${r.id}')`,true,'orders'):''}`)}
function ownerReceptionInfo(){const names=Object.values(state.staffProfiles||{}).filter(p=>p.status==='active'&&p.canReceive).map(p=>p.name);return `<section class="owner-reception-info"><span>${icon('location')}</span><div><strong>${names.length===1?'Encargada de recepción':'Trabajadoras habilitadas en el local'}</strong><p>${esc(names.join(' · ')||'Todavía no hay una encargada habilitada.')}</p><small>Es una función del equipo. No requiere otro tipo de cuenta.</small></div><button onclick="staffTab='profiles';ownerNavigate('members')">Cambiar encargada →</button></section>`}
function ownerReceptionShortcut(){return `<section class="owner-reception-shortcut"><div>${icon('location')}<span><strong>Prendas de clientes</strong><small>${Object.values(state.staffProfiles||{}).filter(p=>p.status==='active'&&p.canReceive).map(p=>esc(p.name)).join(' · ')||'Sin encargada habilitada'} · ${state.repairs.filter(r=>r.receivedBy).length} ${state.repairs.filter(r=>r.receivedBy).length===1?'prenda registrada':'prendas registradas'}</small></span></div><button onclick="ownerNavigate('reception')">Ver prendas de clientes ${icon('arrow')}</button></section>`}
render=function(){beforeReceptionRender();if(currentPerson==='Dueña'){if(page==='reception')main.innerHTML=receptionPage()+personaControl();else if(!ownerDemo&&['overview','inicio'].includes(page)){const kpis=main.querySelector('.owner-kpis');if(kpis)kpis.insertAdjacentHTML('afterend',ownerReceptionShortcut())}return}const p=staffProfile(currentPerson);if(page==='reception'){main.innerHTML=receptionPage()+personaControl()}if(p.canReceive){const nav=document.getElementById('mobile-nav');const helpButton=[...nav.querySelectorAll('button')].find(b=>b.textContent.trim()==='Ayuda');if(helpButton)helpButton.outerHTML=`<button class="${page==='reception'?'active':''}" ${page==='reception'?'aria-current="page"':''} onclick="navigate('reception')">${icon('location')}<span>Clientes</span></button>`;if(page==='inicio'&&!selectedRepair){const receive=main.querySelector('.receive-new');if(receive){receive.innerHTML=icon('location')+' Ver prendas de clientes';receive.onclick=()=>navigate('reception')}}}};
if(new URLSearchParams(location.search).get('vista')==='recepcion'){currentPerson='Rosa';page='reception'}

;
// published-guides.js
(function(root){
  const published=[{
    id:'PUB-TUTORIAL-TALLER-20261018',title:'Tutorial del taller',folder:'costura',
    applies:'Todos los trabajos',goal:'Video de apoyo del taller. Si tienes dudas sobre el proceso, consulta a la dueña.',
    steps:'',mistakes:'',version:1,hidden:false,
    publicUrl:'videos/tutorial-74a0c17251ac.mp4',mediaName:'Tutorial del taller.mp4'
  }];
  function sync(guides,items=published){
    for(const item of items){
      const existing=guides.find(g=>g.id===item.id);
      if(!existing)guides.push({...item,publishedVersion:item.version});
      else if(existing.publicUrl&&(existing.publishedVersion||0)<item.version){
        const hidden=existing.hidden;Object.assign(existing,item,{hidden,publishedVersion:item.version});
      }
    }
  }
  const tutorials={published,sync};
  if(typeof module==='object'&&module.exports)module.exports=tutorials;else root.RapicosturaTutorials=tutorials;
})(typeof globalThis!=='undefined'?globalThis:this);

;
// guides.js
const beforeGuidesRender=render,previousOwnerAlerts=ownerAlerts,previousAlertCard=alertCard;
const guideFolders=[{id:'recepcion',title:'Recibir prendas',sub:'Registrar lo que pidió el cliente.',icon:'location',color:'lilac'},{id:'costura',title:'Costura y acabados',sub:'Así debe quedar cada arreglo.',icon:'shirt',color:'rose'},{id:'calidad',title:'Revisar la calidad',sub:'Qué comprobar antes de entregar.',icon:'check',color:'blue'},{id:'entregas',title:'Empaque y entregas',sub:'Cuidar e identificar las prendas.',icon:'box',color:'sand'}];
const guideTasks=['Todos los trabajos','Recepción de prendas','Hacer basta','Cambiar cierre','Ajustar talla','Control de calidad','Empaque y entregas'];
let guideFolder='all',guideSearch='',selectedGuide=null,guideObjectURL=null;
function initGuides(){state.workGuides??=[];state.guideReviews??={};state.guideQuestions??=[];RapicosturaTutorials.sync(state.workGuides)}
initGuides();
function guideById(id){return state.workGuides.find(g=>g.id===id)}
function openGuides(folder='all'){selectedGuide=null;guideFolder=folder;guideSearch='';selectedRepair=null;page='guides';render();scrollAppTop()}
function openGuide(id){const g=guideById(id);if(!g||g.hidden&&currentPerson!=='Dueña')return;selectedGuide=id;selectedRepair=null;page='guides';render();scrollAppTop()}
function visibleGuides(){return state.workGuides.filter(g=>!g.hidden||currentPerson==='Dueña')}
function guideCountLabel(n){return n+' '+(n===1?'video':'videos')+' para el equipo'}
function guideCard(g){const f=guideFolders.find(f=>f.id===g.folder),review=state.guideReviews[currentPerson+':'+g.id];return `<button class="guide-video-card" onclick="openGuide('${g.id}')"><span class="guide-video-icon ${f.color}">${icon('play')}</span><span><strong>${esc(g.title)}</strong><small>${esc(f.title)} · Versión ${g.version}</small><em>${g.hidden?'Oculta para el equipo':review?.version===g.version?'Ya la revisaste':'Video de la dueña'}</em></span><b>›</b></button>`}
function guideLibrary(){const owner=currentPerson==='Dueña',folder=guideFolders.find(f=>f.id===guideFolder),list=visibleGuides().filter(g=>(guideFolder==='all'||g.folder===guideFolder)&&`${g.title} ${g.goal} ${g.applies}`.toLowerCase().includes(guideSearch.toLowerCase()));return `${folder?'<button class="back-link" onclick="openGuides()">← Todas las carpetas</button>':''}<div class="greeting"><p class="eyebrow">ASÍ LO HACEMOS EN RAPICOSTURA</p><h1>${folder?folder.title:'Videos del taller'}</h1><p class="sub">${owner?'Comparte tu manera de trabajar con todo el equipo.':'Mira cómo quiere la dueña que hagamos cada proceso.'}</p></div>${!folder?`<section class="guides-hero"><span>${icon('play')}</span><div><h2>Una misma forma de trabajar.</h2><p>Videos claros, paso a paso, para cuidar cada prenda.</p>${owner?'<button onclick="guideEditor()">'+icon('plus')+' Subir un video</button>':''}</div></section><div class="guide-folders">${guideFolders.map(f=>`<button class="guide-folder ${f.color}" onclick="openGuides('${f.id}')"><span>${icon(f.icon)}</span><div><strong>${f.title}</strong><p>${f.sub}</p><small>${guideCountLabel(state.workGuides.filter(g=>g.folder===f.id&&!g.hidden).length)}</small></div><b>›</b></button>`).join('')}</div>`:owner?button('Subir video a esta carpeta','guideEditor()',true,'plus'):''}<div class="section-label"><h2>${folder?'Videos de esta carpeta':'Todos los videos'}</h2><span>${list.length}</span></div><input id="guide-search" class="owner-search" aria-label="Buscar un video" placeholder="Buscar un video…" value="${esc(guideSearch)}"><div id="guide-results" class="guide-results">${list.map(guideCard).join('')||guideEmpty(owner)}</div><p class="local-note">Los tutoriales publicados con la app están disponibles para todo el equipo. Las confirmaciones y los videos que subas desde este dispositivo se guardan aquí.</p>`}
function guideEmpty(owner){return `<div class="guides-empty">${icon('play')}<h3>${guideSearch?'No encontramos una guía':owner?'Todavía no hay videos':'No hay videos disponibles todavía'}</h3><p>${guideSearch?'Prueba con otro nombre o proceso.':owner?'Graba cómo haces el proceso y súbelo con una indicación clara.':'Cuando la dueña publique un video, podrás verla aquí.'}</p></div>`}
paths.play='<rect x="3" y="4" width="18" height="16" rx="4"/><path d="m10 8 6 4-6 4V8Z"/>';
function guideTaskOptions(){return [...new Set([...guideTasks,...state.repairs.map(r=>r.task)])]}
function guideEditor(id){if(currentPerson!=='Dueña')return;const old=id?guideById(id):null;modal(old?'Actualizar guía':'Subir video del taller',`<form id="guide-form"><label class="field">Nombre de la guía<input id="guide-title" maxlength="90" value="${esc(old?.title||'')}" placeholder="Ej. Cómo debe quedar una basta" required></label><label class="field">Carpeta<select id="guide-folder">${guideFolders.map(f=>`<option value="${f.id}" ${(old?.folder||guideFolder)===f.id?'selected':''}>${f.title}</option>`).join('')}</select></label><label class="field">Se aplica a<select id="guide-applies">${staffPick(guideTaskOptions(),old?.applies||'Todos los trabajos')}</select></label><label class="field">${old?'Reemplazar video (opcional)':'Video del proceso'}<input id="guide-upload" type="file" accept="video/*" ${old?'':'required'}></label><label class="field">¿Cómo debe quedar el trabajo?<textarea id="guide-goal" maxlength="700" placeholder="Ej. La costura debe quedar pareja y ambas piernas del mismo largo." required>${esc(old?.goal||'')}</textarea></label><details class="guide-extra"><summary>Añadir pasos y errores a evitar (opcional)</summary><label class="field">Pasos importantes, uno por línea<textarea id="guide-steps" maxlength="1600" placeholder="1. Confirmar la medida\n2. Marcar ambas piernas\n3. Revisar el acabado">${esc(old?.steps||'')}</textarea></label><label class="field">Errores que deben evitarse<textarea id="guide-mistakes" maxlength="700" placeholder="Ej. No cortar antes de comprobar la medida.">${esc(old?.mistakes||'')}</textarea></label></details><p class="local-note">Video de hasta 100 MB. Para reproducirlo en más equipos, usa MP4 o WebM compatible. Este prototipo lo guarda en el navegador.</p><div class="modalactions"><button class="btn" type="button" onclick="dialog.close()">Volver</button><button class="btn primary" id="guide-publish">${old?'Publicar nueva versión':'Publicar guía'}</button></div></form>`);document.getElementById('guide-form').onsubmit=async e=>{e.preventDefault();const file=document.getElementById('guide-upload').files[0];if(file&&(!file.type.startsWith('video/')||file.size>100*1024*1024)){toast('Elige un video de hasta 100 MB.');return}if(!old&&!file)return;const title=document.getElementById('guide-title').value.trim(),goal=document.getElementById('guide-goal').value.trim();if(!title||!goal)return;const g={...old,id:old?.id||'GUI-'+Date.now().toString(36).toUpperCase(),title,folder:document.getElementById('guide-folder').value,applies:document.getElementById('guide-applies').value,goal,steps:document.getElementById('guide-steps').value.trim(),mistakes:document.getElementById('guide-mistakes').value.trim(),version:(old?.version||0)+1,hidden:old?.hidden||false,updatedAt:Date.now(),mediaKey:old?.mediaKey,mediaName:old?.mediaName};const submit=document.getElementById('guide-publish');submit.disabled=true;submit.textContent='Guardando video…';try{if(file){delete g.publicUrl;g.mediaKey=g.id+'-v'+g.version;g.mediaName=file.name;await mediaPut(g.mediaKey,file)}if(old)state.workGuides[state.workGuides.findIndex(x=>x.id===old.id)]=g;else state.workGuides.push(g);dialog.close();selectedGuide=g.id;page='guides';save('La dueña publicó '+g.title+' · Versión '+g.version+'.');toast('Guía publicada para el equipo en este navegador.')}catch{submit.disabled=false;submit.textContent=old?'Publicar nueva versión':'Publicar guía';toast('No se pudo guardar el video. Prueba con uno más pequeño.')}}}
function guideDetail(){const g=guideById(selectedGuide);if(!g||g.hidden&&currentPerson!=='Dueña')return guideEmpty(currentPerson==='Dueña');const f=guideFolders.find(f=>f.id===g.folder),owner=currentPerson==='Dueña',review=state.guideReviews[currentPerson+':'+g.id],questions=state.guideQuestions.filter(q=>q.guideId===g.id&&(owner||q.who===currentPerson));return `<button class="back-link" onclick="openGuides('${g.folder}')">← ${f.title}</button><div class="greeting"><p class="eyebrow">VIDEO DE LA DUEÑA · VERSIÓN ${g.version}${g.hidden?' · OCULTO':''}</p><h1>${esc(g.title)}</h1><p class="sub">${esc(g.applies)}</p></div><section class="guide-player-panel"><div id="guide-player" class="guide-player"><span>Cargando el video guardado…</span></div><div class="guide-standard"><span>${icon('check')} ASÍ DEBE QUEDAR</span><p>${esc(g.goal)}</p></div>${g.steps?`<h2>Pasos importantes</h2><ol class="guide-steps">${g.steps.split('\n').filter(s=>s.trim()).map(s=>`<li>${esc(s.replace(/^\d+[.)]\s*/,''))}</li>`).join('')}</ol>`:''}${g.mistakes?`<div class="guide-mistakes"><strong>${icon('alert')} Evita estos errores</strong><p>${esc(g.mistakes)}</p></div>`:''}${owner?`<div class="worker-actions">${button('Editar guía',`guideEditor('${g.id}')`,true,'orders')}${button(g.hidden?'Volver a mostrar al equipo':'Ocultar al equipo',`guideVisibility('${g.id}')`,false)}</div><p class="local-note">Revisiones declaradas de esta versión: ${Object.values(state.guideReviews).filter(r=>r.guideId===g.id&&r.version===g.version).length}. Son declaraciones de las trabajadoras; no evalúan la calidad del trabajo.</p>`:`<div class="worker-actions">${button(review?.version===g.version?'Ya la revisaste':'Ya revisé esta guía',`markGuideReviewed('${g.id}')`,true,'check')}${button('Tengo una duda',`askGuide('${g.id}')`,false,'help')}</div><p class="local-note">Marca la revisión solo después de consultarla. No necesitas confirmar nada para reproducir el video.</p>`}</section>${questions.length?`<section class="guide-questions"><h2>${owner?'Dudas del equipo':'Mis dudas sobre esta guía'}</h2>${questions.map(q=>`<article><strong>${esc(q.who)} · Versión ${q.version}</strong><p>${esc(q.text)}</p>${q.answer?`<div><strong>Respuesta de la dueña</strong><p>${esc(q.answer)}</p></div>`:owner?button('Responder duda',`answerGuide('${q.id}')`,false,'help'):'<small>La dueña todavía no ha respondido.</small>'}</article>`).join('')}</section>`:''}`}
async function loadGuideVideo(){const g=guideById(selectedGuide),target=document.getElementById('guide-player');if(!g||!target)return;try{let source=g.publicUrl;if(!source){const db=await mediaDB();let blob;try{blob=await new Promise((resolve,reject)=>{const request=db.transaction('files').objectStore('files').get(g.mediaKey);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}finally{db.close()}if(!target.isConnected)return;if(!blob){target.innerHTML='<p>El video no está guardado en este navegador. La dueña debe volver a subirlo aquí.</p>';return}guideObjectURL=URL.createObjectURL(blob);source=guideObjectURL}if(!target.isConnected)return;const video=document.createElement('video');video.src=source;video.controls=true;video.playsInline=true;video.preload='metadata';video.setAttribute('aria-label',g.title);video.onerror=()=>{if(target.isConnected)target.innerHTML=g.publicUrl?'<p>No pudimos cargar el video. Revisa tu conexión y vuelve a abrir esta guía.</p>':'<p>No se pudo reproducir este archivo. Prueba con un MP4 o WebM compatible.</p>'};target.replaceChildren(video)}catch{if(target.isConnected)target.innerHTML='<p>No se pudo cargar el video. Intenta abrir la guía otra vez.</p>'}}
function markGuideReviewed(id){const g=guideById(id);if(!g||g.hidden||currentPerson==='Dueña')return;if(state.guideReviews[currentPerson+':'+id]?.version===g.version){toast('Ya registraste la revisión de esta versión.');return}state.guideReviews[currentPerson+':'+id]={guideId:id,who:currentPerson,version:g.version,at:Date.now()};save(currentPerson+' confirmó que revisó la guía '+g.title+' · Versión '+g.version+'.');toast('Revisión guardada. Puedes volver a ver el video cuando quieras.')}
function guideVisibility(id){const g=guideById(id);if(currentPerson!=='Dueña'||!g)return;modal(g.hidden?'Mostrar esta guía':'Ocultar esta guía',`<p>${g.hidden?'Volverá a estar disponible para el equipo.':'Dejará de aparecer para las trabajadoras. La dueña podrá mostrarla nuevamente.'}</p><div class="modalactions">${button('Volver','dialog.close()')}${button('Confirmar',`confirmGuideVisibility('${id}')`,true)}</div>`)}
function confirmGuideVisibility(id){const g=guideById(id);if(currentPerson!=='Dueña'||!g)return;g.hidden=!g.hidden;dialog.close();save('La dueña '+(g.hidden?'ocultó':'volvió a mostrar')+' la guía '+g.title+'.')}
function askGuide(id){const g=guideById(id);if(!g||currentPerson==='Dueña')return;modal('Preguntar sobre esta guía',`<form id="guide-question-form"><p>${esc(g.title)}</p><label class="field">¿Qué necesitas aclarar?<textarea id="guide-question-text" maxlength="500" placeholder="Ej. Mi máquina es distinta. ¿Cómo puedo hacer este paso?" required></textarea></label><p class="local-note">Es una consulta dentro del prototipo. No se envía un WhatsApp.</p><div class="modalactions"><button class="btn" type="button" onclick="dialog.close()">Volver</button><button class="btn primary">Guardar mi duda</button></div></form>`);document.getElementById('guide-question-form').onsubmit=e=>{e.preventDefault();const text=document.getElementById('guide-question-text').value.trim();if(!text)return;state.guideQuestions.push({id:'DUD-'+Date.now().toString(36).toUpperCase(),guideId:id,version:g.version,who:currentPerson,text,answer:'',at:Date.now()});dialog.close();save(currentPerson+' dejó una duda sobre la guía '+g.title+'.');toast('Tu duda quedó registrada para la dueña.')}}
function answerGuide(id){const q=state.guideQuestions.find(q=>q.id===id);if(!q||currentPerson!=='Dueña')return;modal('Responder a '+esc(q.who),`<form id="guide-answer-form"><div class="notice">${esc(q.text)}</div><label class="field">Tu explicación<textarea id="guide-answer-text" maxlength="700" required></textarea></label><div class="modalactions"><button class="btn" type="button" onclick="dialog.close()">Volver</button><button class="btn primary">Guardar respuesta</button></div></form>`);document.getElementById('guide-answer-form').onsubmit=e=>{e.preventDefault();const text=document.getElementById('guide-answer-text').value.trim();if(!text)return;q.answer=text;q.answeredAt=Date.now();dialog.close();save('La dueña respondió una duda de '+q.who+' sobre un proceso del taller.');toast('Respuesta guardada.')}}
ownerAlerts=function(){initGuides();return [...previousOwnerAlerts(),...(ownerDemo?[]:state.guideQuestions.filter(q=>!q.answer).map(q=>({kind:'help',title:q.who+' tiene una duda',description:guideById(q.guideId)?.title||'Guía del taller',guide:q.guideId,label:'Ver duda',icon:'play'})))]};
alertCard=function(a){return a.guide?`<div class="owner-alert help"><span>${icon('help')}</span><div><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><button onclick="openGuide('${a.guide}')">Ver duda →</button></div></div>`:previousAlertCard(a)};
function relatedGuides(task){return state.workGuides.filter(g=>!g.hidden&&(g.applies==='Todos los trabajos'||g.applies===task))}
render=function(){initGuides();if(guideObjectURL){URL.revokeObjectURL(guideObjectURL);guideObjectURL=null}beforeGuidesRender();const inGuides=page==='guides';if(inGuides){main.innerHTML=(selectedGuide?guideDetail():guideLibrary())+personaControl();const search=document.getElementById('guide-search');if(search)search.oninput=e=>{guideSearch=e.target.value;const list=visibleGuides().filter(g=>(guideFolder==='all'||g.folder===guideFolder)&&`${g.title} ${g.goal} ${g.applies}`.toLowerCase().includes(guideSearch.toLowerCase()));document.getElementById('guide-results').innerHTML=list.map(guideCard).join('')||guideEmpty(currentPerson==='Dueña')};if(selectedGuide)loadGuideVideo()}else if(selectedRepair&&currentPerson!=='Dueña'){const r=selected(),related=r?relatedGuides(r.task):[];if(related.length){const panel=main.querySelector('.task-body')||main.querySelector('.panel');if(panel)panel.insertAdjacentHTML('beforeend',`<section class="related-guides"><h3>${icon('play')} Así lo quiere la dueña</h3>${related.slice(0,3).map(guideCard).join('')}</section>`)}}else if(page==='reception'&&currentPerson!=='Dueña'&&relatedGuides('Recepción de prendas').length){main.querySelector('.greeting')?.insertAdjacentHTML('afterend','<button class="guides-shortcut" onclick="openGuides(\'recepcion\')">'+icon('play')+' Ver cómo recibimos una prenda</button>')}const nav=document.getElementById('mobile-nav');const item=document.createElement('button');item.className=inGuides?'active':'';if(inGuides){for(const b of nav.querySelectorAll('button')){b.classList.remove('active');b.removeAttribute('aria-current')}item.setAttribute('aria-current','page')}item.innerHTML=icon('play')+'<span>Guías</span>';item.onclick=()=>openGuides();nav.insertBefore(item,nav.children[currentPerson==='Dueña'?2:1]||null);nav.classList.add('with-guides')};
window.addEventListener('storage',event=>{if(event.key==='hilando-v1'&&currentPerson!=='Dueña'&&page==='guides'){initGuides();render()}});
if(new URLSearchParams(location.search).get('seccion')==='guias')page='guides';

;
// branches.js
let ownerBranch='Todas';
const branchBeforeRender=render,branchBeforeSaveIntake=saveIntake,branchBeforeReceive=receiveGarment,branchBeforeStaffCard=staffCard,branchBeforeMemberCard=memberCard,branchBeforeOwnerData=ownerData,branchBeforeReceptionCard=receptionCard;
function knownBranch(value){return Boolean(value&&value!=='Por confirmar'&&value!=='Sin sede')}
function responsibleBranch(r){return r.responsibleBranch||r.branch||'Por confirmar'}
function branchNames(){return [...new Set([...staffBranches.slice(1),...Object.values(state.staffProfiles||{}).map(p=>p.branch),...state.repairs.map(responsibleBranch)].filter(knownBranch))]}
function branchOptions(value,placeholder='Elige una sede'){return `<option value="">${placeholder}</option>`+branchNames().map(b=>`<option value="${esc(b)}" ${b===value?'selected':''}>${esc(b)}</option>`).join('')}
function branchMatches(r){return ownerBranch==='Todas'||(ownerBranch==='Sin sede'?!knownBranch(responsibleBranch(r)):responsibleBranch(r)===ownerBranch)}
function setOwnerBranch(value){ownerBranch=value;render()}
function branchFilter(){return `<section class="branch-filter"><label for="owner-branch">${icon('location')} Sede responsable<select id="owner-branch" onchange="setOwnerBranch(this.value)"><option>Todas</option>${branchNames().map(b=>`<option ${ownerBranch===b?'selected':''}>${esc(b)}</option>`).join('')}<option ${ownerBranch==='Sin sede'?'selected':''}>Sin sede</option></select></label><p>Filtra por el local que responde al cliente, aunque la prenda esté en otro lugar.</p></section>`}
function ownerBranchSummary(){const rows=branchBeforeOwnerData().repairs,names=branchNames();if(rows.some(r=>!knownBranch(responsibleBranch(r))))names.push('Sin sede');return `<section class="branch-summary"><h2>${icon('location')} Las sedes del taller</h2><p>Cada pedido conserva su sede hasta la entrega al cliente.</p><div>${names.map(b=>{const repairs=rows.filter(r=>(b==='Sin sede'?!knownBranch(responsibleBranch(r)):responsibleBranch(r)===b)&&r.stage!=='delivered');return `<button onclick="openBranchReception(this.dataset.branch)" data-branch="${esc(b)}"><strong>${esc(b)}</strong><span>${repairs.length} ${repairs.length===1?'prenda activa':'prendas activas'}</span></button>`}).join('')}</div></section>`}
function openBranchReception(branch){ownerBranch=branch;ownerNavigate('reception')}
function initBranches(){initWorkScope();for(const r of state.repairs)r.responsibleBranch||=r.branch||'Por confirmar';if(typeof RapicosturaBranches!=='undefined'){RapicosturaBranches.extend(state.branchCatalog);RapicosturaBranches.extend(branchNames());state.branchCatalog=[...RapicosturaBranches.sites];for(const name of RapicosturaBranches.sites)if(!staffBranches.includes(name))staffBranches.push(name)}else for(const p of Object.values(state.staffProfiles||{}))if(knownBranch(p.branch)&&!staffBranches.includes(p.branch))staffBranches.push(p.branch)}
function chooseStaffBranch(name=currentPerson){if(currentPerson!=='Dueña'&&name!==currentPerson)return;const p=staffProfile(name);modal('Sede de referencia','<form id="branch-profile-form"><label class="field">Sede de referencia<select id="branch-profile-value" required>'+branchOptions(p.branch)+'</select></label><div class="modalactions"><button type="button" class="btn" onclick="dialog.close()">Volver</button><button class="btn primary">Guardar sede</button></div></form>');document.getElementById('branch-profile-form').onsubmit=e=>{e.preventDefault();const value=document.getElementById('branch-profile-value').value;if(!branchNames().includes(value))return;p.branch=value;dialog.close();save(name+' actualizó su sede de referencia a '+value+'.')}}
staffCard=function(p){if(ownerBranch!=='Todas'&&(ownerBranch==='Sin sede'?knownBranch(p.branch):p.branch!==ownerBranch))return '';return branchBeforeStaffCard(p).replace('</section>','<button class="branch-assign" onclick="chooseStaffBranch(\''+esc(p.name)+'\')">Asignar sede</button></section>')};
memberCard=function(name){const p=staffProfile(name);if(ownerBranch!=='Todas'&&!ownerData().repairs.some(r=>holder(r.id)===name)&&(ownerBranch==='Sin sede'?knownBranch(p.branch):p.branch!==ownerBranch))return '';return branchBeforeMemberCard(name)};
receiveGarment=function(keep=false){if(!staffProfile(currentPerson).canReceive){toast('La dueña debe habilitarte para recibir prendas en el local.');return}branchBeforeReceive(keep===true);const select=document.getElementById('intake-branch');if(select&&intakeDraft){select.innerHTML=branchOptions(intakeDraft.branch||staffProfile(currentPerson).branch);select.required=true;select.closest('label').firstChild.textContent='Sede responsable del cliente'}};
saveIntake=function(){if(!intakeDraft||!branchNames().includes(intakeDraft.branch)){toast('Elige la sede que recibe al cliente.');return}const branch=intakeDraft.branch;if(!knownBranch(staffProfile(currentPerson).branch))staffProfile(currentPerson).branch=branch;branchBeforeSaveIntake()};
ownerData=function(){const d=branchBeforeOwnerData();if(ownerBranch==='Todas')return d;return {repairs:d.repairs.filter(branchMatches),agreements:d.agreements.filter(a=>a.repairIds.some(id=>{const r=d.repairs.find(r=>r.id===id);return r&&branchMatches(r)}))}};
receptionRecords=function(){return state.repairs.filter(r=>r.receivedBy&&(currentPerson==='Dueña'?branchMatches(r):r.receivedBy===currentPerson)).sort((a,b)=>(b.receivedAt||0)-(a.receivedAt||0))};
receptionCard=function(r){return branchBeforeReceptionCard(r).replace('</em>','</em><small>Sede responsable: '+esc(responsibleBranch(r))+'</small>')};
function canReview(r){return currentPerson!=='Dueña'&&staffProfile(currentPerson).canReceive&&knownBranch(staffProfile(currentPerson).branch)&&staffProfile(currentPerson).branch===responsibleBranch(r)}
function openQuality(id){const r=state.repairs.find(r=>r.id===id);if(!r||!canReview(r)||r.stage!=='review')return;modal('Revisar calidad · '+esc(r.id),'<form id="quality-form"><p>'+esc(r.garment)+' · '+esc(r.task)+'</p><p>'+esc(r.instructions||'')+'</p><p>Revisa físicamente la prenda antes de aprobar.</p><label class="choose-row"><input id="quality-present" type="checkbox" required><span>Puedo revisar esta prenda aquí y ahora.</span></label><label class="choose-row"><input id="quality-correct" type="checkbox" required><span>El arreglo, las costuras y el acabado cumplen lo acordado.</span></label><div class="modalactions"><button class="btn" type="button" onclick="requestCorrection(\''+id+'\')">Necesita corrección</button><button class="btn primary">Aprobar calidad</button></div></form>');document.getElementById('quality-form').onsubmit=e=>{e.preventDefault();finishQuality(id,document.getElementById('quality-present').checked&&document.getElementById('quality-correct').checked)}}
function finishQuality(id,checked){const r=state.repairs.find(r=>r.id===id);if(!r||!canReview(r)||r.stage!=='review'||!checked)return;r.stage='ready';r.reviewedBy=currentPerson;r.reviewedAt=Date.now();r.issue='';dialog.close();save(currentPerson+' aprobó la calidad de '+id+'. Lista para el cliente.')}
function requestCorrection(id){const r=state.repairs.find(r=>r.id===id);if(!r||!canReview(r)||r.stage!=='review')return;modal('¿Qué debe corregirse?','<form id="quality-correction"><label class="field">Detalle de la corrección<textarea id="quality-note" maxlength="500" required></textarea></label><button class="btn primary">Guardar corrección</button></form>');document.getElementById('quality-correction').onsubmit=e=>{e.preventDefault();const note=document.getElementById('quality-note').value.trim();if(!note||!canReview(r)||r.stage!=='review')return;r.stage='working';r.issue=note;dialog.close();save(currentPerson+' pidió corregir '+id+': '+note)}}
function deliverToClient(id){const r=state.repairs.find(r=>r.id===id);if(!r||!canReview(r)||r.stage!=='ready')return;modal('Entregar al cliente','<p>¿Ya devolviste '+esc(r.garment)+' a '+esc(r.client)+'?</p><div class="modalactions">'+button('Todavía no','dialog.close()')+button('Sí, entregada al cliente',"confirmClientDelivery('"+id+"')",true)+'</div>')}
function confirmClientDelivery(id){const r=state.repairs.find(r=>r.id===id);if(!r||!canReview(r)||r.stage!=='ready')return;r.stage='delivered';r.deliveredBy=currentPerson;r.deliveredAt=Date.now();dialog.close();save(currentPerson+' entregó '+id+' al cliente.')}
function qualityQueue(){const rows=state.repairs.filter(r=>canReview(r)&&['review','ready'].includes(r.stage));return rows.length?'<section class="profile-sheet"><h2>Calidad y entrega al cliente</h2>'+rows.map(r=>'<div class="branch-return-row"><strong>'+esc(r.garment)+' · '+r.id+'</strong><p>'+repairLabels[r.stage]+'</p>'+button(r.stage==='review'?'Revisar calidad':'Entregar al cliente',r.stage==='review'?"openQuality('"+r.id+"')":"deliverToClient('"+r.id+"')",true,'check')+'</div>').join('')+'</section>':''}
render=function(){initBranches();branchBeforeRender();if(currentPerson==='Dueña'&&['overview','inicio','members','reception','movements','attention'].includes(page)){const heading=main.querySelector('.owner-heading,.greeting');heading?.insertAdjacentHTML('afterend',branchFilter());if(['overview','inicio'].includes(page))main.querySelector('.owner-kpis')?.insertAdjacentHTML('afterend',ownerBranchSummary())}else if(currentPerson!=='Dueña'&&page==='reception'){main.querySelector('.greeting')?.insertAdjacentHTML('afterend',qualityQueue())}};

